@Test
public void testFuntionality1() {
    BlockingBatchingRowSet set = new BlockingBatchingRowSet(10);
    IRowMeta rm = createRowMetaInterface();
    List<Object[]> rows = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        rows.add(new Object[] { new Long(i) });
    }
    assertEquals(0, set.size());
    // Pop off row. This should return null (no row available: has a timeout)
    //
    Object[] r = set.getRow();
    assertNull(r);
    // Add rows. set doesn't report rows, batches them
    // this batching row set has 2 buffers with 2 rows, the 5th row will cause the rows to be
    // exposed.
    //
    int index = 0;
    while (index < 4) {
        set.putRow(rm, rows.get(index++));
        assertEquals(0, set.size());
    }
    set.putRow(rm, rows.get(index++));
    assertEquals(5, set.size());
    // Signal done...
    //
    set.setDone();
    assertTrue(set.isDone());
    // Get a row back...
    //
    r = set.getRow();
    assertNotNull(r);
    assertArrayEquals(rows.get(0), r);
    // Get a row back...
    //
    r = set.getRow();
    assertNotNull(r);
    assertArrayEquals(rows.get(1), r);
    // Get a row back...
    //
    r = set.getRow();
    assertNotNull(r);
    assertArrayEquals(rows.get(2), r);
}

@Test
public void testClass() {
    BlockingListeningRowSet rowSet = new BlockingListeningRowSet(1);
    assertEquals(0, rowSet.size());
    final Object[] row = new Object[] {};
    final RowMeta meta = new RowMeta();
    rowSet.putRow(meta, row);
    assertSame(meta, rowSet.getRowMeta());
    assertEquals(1, rowSet.size());
    assertFalse(rowSet.isBlocking());
    assertSame(row, rowSet.getRow());
    assertEquals(0, rowSet.size());
    rowSet.putRow(meta, row);
    assertSame(row, rowSet.getRowImmediate());
    rowSet.putRow(meta, row);
    assertEquals(1, rowSet.size());
    rowSet.clear();
    assertEquals(0, rowSet.size());
}

@Test
public void testClass() {
    final int type = ICheckResult.TYPE_RESULT_ERROR;
    final String text = "some text";
    final String sourceMetaName = "meta name";
    final ICheckResultSource sourceMeta = mock(ICheckResultSource.class);
    final String errorCode = "error code";
    CheckResult cr = new CheckResult();
    assertEquals(ICheckResult.TYPE_RESULT_NONE, cr.getType());
    assertTrue(cr.getTypeDesc() != null && cr.getTypeDesc().isEmpty());
    cr.setType(type);
    assertEquals(type, cr.getType());
    assertTrue(cr.getText().isEmpty());
    cr.setText(text);
    assertSame(text, cr.getText());
    assertNull(null, cr.getSourceInfo());
    assertNull(cr.getErrorCode());
    cr.setErrorCode(errorCode);
    assertSame(errorCode, cr.getErrorCode());
    when(sourceMeta.getName()).thenReturn(sourceMetaName);
    cr = new CheckResult(type, text, sourceMeta);
    assertSame(sourceMeta, cr.getSourceInfo());
    assertTrue(cr.getTypeDesc() != null && !cr.getTypeDesc().isEmpty());
    final String stringValue = String.format("%s: %s (%s)", cr.getTypeDesc(), text, sourceMetaName);
    assertEquals(stringValue, cr.toString());
    cr = new CheckResult(type, errorCode, text, sourceMeta);
    assertSame(errorCode, cr.getErrorCode());
}

