    long[] l1 = new long[] { 1 };
    long[] l2 = new long[] { 1, 2 };
    long[] l3 = new long[] { 1, 2, 3 };
    short[] sh1 = new short[] { 1 };
    short[] sh2 = new short[] { 1, 2 };
    short[] sh3 = new short[] { 1, 2, 3 };
    boolean[] b1 = new boolean[] { true };
    boolean[] b2 = new boolean[] { true, false };
