@Test
public void testTransformListenersConcurrentModification() throws InterruptedException {
    // Create a base transform
    final BaseTransform baseTransform = new BaseTransform(mockHelper.transformMeta, mockHelper.iTransformMeta, mockHelper.iTransformData, 0, mockHelper.pipelineMeta, mockHelper.pipeline);
    // Create thread to dynamically add listeners
    final AtomicBoolean done = new AtomicBoolean(false);
    Thread addListeners = new Thread() {

        @Override
        public void run() {
            while (!done.get()) {
                baseTransform.addTransformFinishedListener(mock(ITransformFinishedListener.class));
                synchronized (done) {
                    done.notify();
                }
            }
        }
    };
    // Mark start and stop while listeners are being added
    try {
        addListeners.start();
        // Allow a few listeners to be added
        synchronized (done) {
            while (baseTransform.getTransformFinishedListeners().size() < 20) {
                done.wait();
            }
        }
        baseTransform.markStart();
        // Allow more listeners to be added
        synchronized (done) {
            while (baseTransform.getTransformFinishedListeners().size() < 100) {
                done.wait();
            }
        }
        baseTransform.markStop();
    } finally {
        // Close addListeners thread
        done.set(true);
        addListeners.join();
    }
}

@Test
public void resultFilesMapIsSafeForConcurrentModification() throws Exception {
    final BaseTransform<ITransformMeta, ITransformData> transform = new BaseTransform(mockHelper.transformMeta, mockHelper.iTransformMeta, mockHelper.iTransformData, 0, mockHelper.pipelineMeta, mockHelper.pipeline);
    final AtomicBoolean complete = new AtomicBoolean(false);
    final int FILES_AMOUNT = 10 * 1000;
    Thread filesProducer = new Thread(() -> {
        try {
            for (int i = 0; i < FILES_AMOUNT; i++) {
                transform.addResultFile(new ResultFile(0, new NonAccessibleFileObject(Integer.toString(i)), null, null));
                try {
                    Thread.sleep(1);
                } catch (Exception e) {
                    fail(e.getMessage());
                }
            }
        } finally {
            complete.set(true);
        }
    });
    filesProducer.start();
    try {
        while (!complete.get()) {
            for (Map.Entry<String, ResultFile> entry : transform.getResultFiles().entrySet()) {
                entry.getKey();
            }
        }
    } finally {
        filesProducer.join();
    }
}

