public void test() throws Exception {
    /*
        check( "COMPATIBILITY_MODE", new IBooleanGetter() {
          public boolean get() {
            return meta.isCompatible();
          }
        } );
    */
    check("OPTIMIZATION_LEVEL", () -> meta.getOptimizationLevel());
